import {useSelectedCopilotSpaceId} from '@github-ui/copilot-chat/hooks/use-selected-custom-copilot-id'
import {AUTO_MODEL_ID, getAutoModel} from '@github-ui/copilot-chat/utils/auto-model'
import {filterUniqueConfirmations, srOnlyHeader} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {MAX_SUBTHREADS_PER_MESSAGE} from '@github-ui/copilot-chat/utils/copilot-chat-manager'
import {getParentMessage} from '@github-ui/copilot-chat/utils/copilot-chat-subthreading-helpers'
import {type CopilotChatMessage, type Invocation, NullMessageId} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
